repo.samples.py:
"""Sample records."""


class Sample:
    def __init__(self, batch, dose):
        self.batch = batch
        self.dose = dose

    def __repr__(self):
        return "Sample(%r, %r)" % (self.batch, self.dose)


ROWS = [('b3', 29), ('b1', 8), ('b4', 36), ('b3', 10), ('b2', 57)]


def load_samples():
    """Yield the stored samples one at a time."""
    for batch, dose in ROWS:
        yield Sample(batch, dose)

repo.journal.py:
"""A book of samples with a cached total."""


class SampleBook:
    def __init__(self):
        self._samples = []
        self._total = None

    def add(self, sample):
        """Add one sample to the book."""
        self._samples.append(sample)

    def total(self):
        """Return the total dose of the samples in the book."""
        if self._total is None:
            self._total = sum(x.dose for x in self._samples)
        return self._total

    def count(self):
        """Return how many samples the book holds."""
        return len(self._samples)


def describe_sample(sample):
    """Return a one-line description of a sample."""
    return "%s: %s" % (sample.batch, sample.dose)

